// 7,000 字版：多益約 700–800 分常見的進階商務詞組。
// 先檢查全字庫，再加入 500 筆不重複的專業名詞片語。
var ADVANCED_BUSINESS_MODIFIERS = [["strategic","策略性"],["regulatory","監管性"],["contractual","合約性"],["operational","營運性"],["financial","財務性"],["corporate","企業"],["executive","高階主管"],["confidential","機密"],["international","國際"],["competitive","競爭性"],["sustainable","永續"],["comprehensive","全面性"],["preliminary","初步"],["prospective","未來潛在"],["mandatory","強制"],["alternative","替代"],["commercial","商業"],["administrative","行政"],["analytical","分析"],["technological","技術"],["organizational","組織"],["legislative","立法"]];
var ADVANCED_BUSINESS_NOUNS = [["initiative","倡議"],["compliance","遵循"],["framework","架構"],["negotiation","談判"],["assessment","評估"],["proposal","提案"],["allocation","分配"],["expenditure","支出"],["acquisition","收購"],["expansion","擴張"],["implementation","執行"],["collaboration","合作"],["infrastructure","基礎設施"],["regulation","規範"],["liability","責任"],["contingency","應變方案"],["compensation","補償"],["productivity","生產力"],["procurement","採購"],["investment","投資"],["forecast","預測"],["evaluation","評量"],["documentation","文件"],["transaction","交易"],["distribution","配送"]];
// These combinations were mechanically generated to increase the card count.
// They are grammatical strings, but most are not established TOEIC phrases and
// should not be learned as independent headwords.
var GENERATED_NONSTANDARD_TERMS = {};
ADVANCED_BUSINESS_MODIFIERS.forEach(function(modifier){
  ADVANCED_BUSINESS_NOUNS.forEach(function(noun){
    GENERATED_NONSTANDARD_TERMS[modifier[0] + " " + noun[0]] = true;
  });
});

// Earlier hand-added combinations with the same issue are retired as well.
// Common fixed phrases such as "flight schedule" are intentionally not listed.
var RETIRED_BUILTIN_TERMS = {
  "requested service": true,
  "requested process": true,
  "urgent survey": true,
  "regular review": true,
  "monthly record": true,
  "future review": true,
  "important update": true,
  "final project": true,
  "international documentation": true,
  "compliance with confidentiality requirements": true
};

function isRetiredBuiltinTerm(term){
  var normalized = String(term || "").trim().toLowerCase();
  return !!RETIRED_BUILTIN_TERMS[normalized] || !!GENERATED_NONSTANDARD_TERMS[normalized];
}

var advancedKnownWords = {};
Object.keys(DECKS).forEach(function(level){ DECKS[level].forEach(function(card){ advancedKnownWords[String(card[0]).toLowerCase()] = true; }); });
var ADVANCED_7000_EXTENSION = [];
// Disabled: this was an automatic adjective+noun phrase generator.
if(false){
ADVANCED_BUSINESS_MODIFIERS.forEach(function(modifier){
  ADVANCED_BUSINESS_NOUNS.forEach(function(noun){
    var phrase = modifier[0] + " " + noun[0];
    if(!advancedKnownWords[phrase] && ADVANCED_7000_EXTENSION.length < 500){
      advancedKnownWords[phrase] = true;
      ADVANCED_7000_EXTENSION.push([phrase, modifier[1] + noun[1], "The team reviewed the " + phrase + " during the meeting.", "團隊在會議中檢視了這項「" + modifier[1] + noun[1] + "」。", "n."]);
    }
  });
});
}
DECKS.advanced.push.apply(DECKS.advanced, ADVANCED_7000_EXTENSION);

// "Confidential compliance" is not an idiomatic legal or business term.
// Replace the generated combination with the standard, precise expression.
DECKS.advanced.forEach(function(card){
  if(card[0] === "confidential compliance"){
    card[0] = "compliance with confidentiality requirements";
    card[1] = "遵守保密要求；保密法遵";
    card[2] = "The company ensures strict compliance with confidentiality requirements when handling sensitive client data.";
    card[3] = "公司在處理敏感客戶資料時，確保嚴格遵守保密要求。";
    card[4] = "n.";
  }
});

// Keep fixed phrases and phrasal verbs, but remove generated combinations and
// the small retired list above from every built-in level before the app loads.
Object.keys(DECKS).forEach(function(level){
  DECKS[level] = DECKS[level].filter(function(card){
    return !isRetiredBuiltinTerm(card[0]);
  });
});

// Restore the total to 7,000 with actual single-word cards, not automatically
// combined adjective+noun strings.  The data file is deliberately separate so
// future vocabulary updates do not require editing this quality-check logic.
var REAL_WORD_EXTENSION_CONTEXTS = {};
if(typeof REAL_WORD_EXTENSION !== "undefined" && Array.isArray(REAL_WORD_EXTENSION)){
  var realWordExtensionKnown = {};
  Object.keys(DECKS).forEach(function(level){
    DECKS[level].forEach(function(card){
      realWordExtensionKnown[String(card[0] || "").trim().toLowerCase()] = true;
    });
  });
  REAL_WORD_EXTENSION.forEach(function(entry){
    var word = String(entry[0] || "").trim();
    var normalizedWord = word.toLowerCase();
    if(word && !realWordExtensionKnown[normalizedWord]){
      realWordExtensionKnown[normalizedWord] = true;
      REAL_WORD_EXTENSION_CONTEXTS[normalizedWord] = entry[3] || "thing";
      // The marker is replaced by a context-appropriate example below.
      DECKS.advanced.push([word, entry[1], "__REAL_WORD_EXTENSION__", "", entry[2] || "n."]);
    }
  });
}

// Example-quality pass ------------------------------------------------------
// Earlier expansion batches used a few repeated filler sentences (for example,
// "We discussed ... during class").  This pass replaces only those generated
// sentences.  It leaves hand-written examples and all card scheduling data alone.
var EXAMPLE_QUALITY_VERSION = "2026-08-14-context-v7";
var QUALITY_LEGACY_EXAMPLE_PATTERNS = [
  /^We discussed the .+ during class\.$/,
  /^We discussed the .+ during today's lesson\.$/,
  /^We discussed the .+ in today's meeting\.$/,
  /^We discussed the topic of .+ in class today\.$/,
  /^We learned how to .+ during today's lesson\.$/,
  /^The lesson included an? .+ example\.$/,
  /^The report includes an? .+ example\.$/,
  /^The report includes information about the .+\.$/,
  /^The report was .+ reviewed\.$/,
  /^The team reviewed the .+ during the meeting\.$/,
  /^The briefing covered the .+ in detail\.?/,
  /^The study focused on the .+\.?/,
  /^The staff kept a record of the .+\.?/,
  /^The plan takes the .+ into account\.?/,
  /^The team identified the .+ as an important factor\.?/,
  /^The next step depends on the .+\.?/,
  /^The .+ was easy to use in daily life\.?/,
  /^She put the .+ away after using it\.?/,
  /^I picked up the .+ from the table\.?/,
  /^The .+ was kept in a safe place\.?/
];

// These longer frames came from an older automatic batch.  They read like a
// project report rather than an example a learner would naturally hear or use.
// Keep them in the detector even when a second generic follow-up sentence was
// attached, so saved cards are refreshed without touching their review dates.
var QUALITY_MODULAR_EXAMPLE_PATTERNS = [
  /^The project included a review of the .+\.?/,
  /^The team compared the available information about the .+\.?/,
  /^The guide explains the role of the .+\.?/,
  /^The report provides details about the .+\.?/,
  /^The manager asked for an update on the .+\.?/,
  /^The staff kept a record of the .+\.?/,
  /^The study focused on the .+\.?/,
  /^The team identified the .+ as an important factor\.?/,
  /^The next step depends on the .+\.?/,
  /^The briefing covered the .+ in detail\.?/,
  /^The plan takes the .+ into account\.?/,
  /^Students learned about .+ in class\.?/,
  /^The lesson used .+ to explain the topic\.?/,
  /^The textbook gives a clear example of .+\.?/,
  /^The .+ follows a fixed routine\.?/,
  /^The .+ requires immediate attention from the responsible team\.?/,
  /^The .+ plays a key role in daily operations\.?/,
  /^The .+ is ready for approval after all revisions\.?/,
  /^The .+ can still be changed before approval\.?/,
  /^The .+ can be accessed securely online\.?/,
  /^Authorized team members can view the .+ together\.?/
];

function isQualityLegacyFillerExample(example){
  var text = String(example || "");
  return QUALITY_LEGACY_EXAMPLE_PATTERNS.some(function(pattern){ return pattern.test(text); }) ||
    QUALITY_MODULAR_EXAMPLE_PATTERNS.some(function(pattern){ return pattern.test(text); });
}

function qualityHash(value){
  // FNV-1a gives a well-spread, stable selection for similarly spelled words.
  var hash = 2166136261;
  String(value).toLowerCase().split("").forEach(function(character){
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  });
  return hash >>> 0;
}

function qualityFormat(template, word, meaning){
  return template.replace(/\{word\}/g, word).replace(/\{meaning\}/g, meaning);
}

